/* eslint-disable jsx-a11y/label-has-associated-control */
import React, { useEffect, useState } from 'react';
import { AlertOctagon, Checkmark2 } from '@hexa-ui/icons';
import { Container, StyledParagraph } from './ProgressMeter.styles';
import { ProgressMeterTypes } from './ProgressMeter.types';

function ProgressMeterComponent(
  {
    label,
    labelPosition,
    value,
    maxValue = 100,
    hasError = false,
    dataTestId,
    ...props
  }: ProgressMeterTypes,
  forwardedRef: React.ForwardedRef<HTMLDivElement>
): JSX.Element {
  const [isCompleted, setIsCompleted] = useState(false);

  useEffect(() => {
    if (value >= maxValue) {
      setIsCompleted(true);
    }
  }, [value, maxValue]);

  return (
    <Container
      hasError={hasError}
      isCompleted={isCompleted}
      labelPosition={labelPosition}
      data-testid={dataTestId}
      {...props}
      ref={forwardedRef}
    >
      {label && (
        <StyledParagraph size="xsmall" alignment={labelPosition} weight="normal">
          {value >= maxValue && !hasError ? (
            <Checkmark2 size="tiny" />
          ) : (
            hasError && <AlertOctagon size="tiny" />
          )}
          {label}
        </StyledParagraph>
      )}
      <progress value={`${value}`} max={`${maxValue}`} />
    </Container>
  );
}

export const ProgressMeter = React.forwardRef(ProgressMeterComponent);
export default ProgressMeter;
